const config = $input.first().json;
for (const [key, limit] of [['question', 6000], ['context', 4000], ['preferred_sources', 2000], ['output_language', 100]]) {
  if (typeof config[key] !== 'string' || !config[key].trim() || config[key].length > limit) {
    throw new Error(key + ' must be non-empty text, at most ' + limit + ' characters.');
  }
  config[key] = config[key].trim();
}
config.country = String(config.country ?? '').trim().toLowerCase();
config.search_language = String(config.search_language ?? '').trim().toLowerCase();
if (!/^[a-z]{2}$/.test(config.country)) throw new Error('Use a two-letter country code.');
if (!/^[a-z0-9-]{1,35}$/.test(config.search_language)) throw new Error('Use a valid search language code.');
if (!Number.isInteger(config.results_per_search) || config.results_per_search < 1 || config.results_per_search > 10) {
  throw new Error('Request 1–10 results per search to keep the model context manageable.');
}
return [{ json: config }];

