const task = $('Validate research task').first().json;
const agent = $input.first().json;
const inspect = ' Inspect the saved Agent execution before retrying paid calls.';
if (typeof agent.output !== 'string' || !agent.output.trim()) throw new Error('The Agent did not return a report.' + inspect);
if (!Array.isArray(agent.intermediateSteps)) throw new Error('Enable Return Intermediate Steps on the Research agent to preserve search evidence.');
const searches = agent.intermediateSteps.map((step, index) => {
  let observation = step.observation;
  if (typeof observation === 'string') {
    try { observation = JSON.parse(observation); }
    catch { throw new Error('Could not decode tool evidence for search ' + (index + 1) + '.' + inspect); }
  }
  const values = Array.isArray(observation) ? observation.flat(Infinity) : [observation];
  const envelopes = values.map(value => value?.json ?? value);
  if (!envelopes.length || envelopes.some(value => !value || typeof value !== 'object')) throw new Error('Missing tool evidence.' + inspect);
  const completed = envelopes.every(value => value.status === 'done' && Array.isArray(value.results?.[0]?.organic));
  const results = completed ? envelopes.flatMap(value => value.results[0].organic) : [];
  return {
    query: step.action?.toolInput?.query ?? null,
    status: completed ? (results.length ? 'results_returned' : 'no_results') : 'tool_error_or_incomplete_response',
    returned_count: completed ? results.length : null,
    credits: completed && envelopes.every(value => typeof value.usage?.credits === 'number' && Number.isFinite(value.usage.credits) && value.usage.credits >= 0) ? envelopes.reduce((sum, value) => sum + value.usage.credits, 0) : null,
    responses: envelopes,
  };
});
const sources = [];
for (const [searchIndex, search] of searches.entries()) {
  if (search.status !== 'results_returned') continue;
  let resultNumber = 0;
  for (const response of search.responses) {
    for (const result of response.results[0].organic) {
      resultNumber += 1;
      if (!result || typeof result.link !== 'string' || !/^https?:\/\/[^\s<>"\\]+$/.test(result.link)) continue;
      sources.push({
        id: 'S' + (searchIndex + 1) + 'R' + resultNumber,
        url: result.link,
        title: typeof result.title === 'string' ? result.title : '',
        snippet: typeof result.snippet === 'string' ? result.snippet : '',
        position: result.position ?? null,
        search_number: searchIndex + 1,
        result_number: resultNumber,
        collected_at: response.created_at ?? null,
      });
    }
  }
}
let report;
try {
  const output = agent.output.trim().replace(/^```(?:json)?\s*\n([\s\S]*?)\n```$/i, '$1');
  report = JSON.parse(output);
} catch { throw new Error('The Agent report must be valid JSON in the requested structure.' + inspect); }
function text(value, field) {
  if (typeof value !== 'string' || !value.trim()) throw new Error('Missing report text: ' + field + '.' + inspect);
  return value.trim();
}
if (!report || typeof report !== 'object' || Array.isArray(report)) throw new Error('The Agent report must be an object.' + inspect);
const summary = text(report.summary, 'summary');
if (!Array.isArray(report.findings) || !Array.isArray(report.open_questions)) throw new Error('Report findings and open_questions must be arrays.' + inspect);
const assessments = ['supported', 'partial', 'not_established', 'conflicting'];
const findings = report.findings.map((finding, index) => {
  if (!finding || typeof finding !== 'object') throw new Error('Invalid finding ' + (index + 1) + '.' + inspect);
  if (!assessments.includes(finding.assessment)) throw new Error('Invalid evidence assessment for finding ' + (index + 1) + '.' + inspect);
  if (!Array.isArray(finding.source_urls)) throw new Error('source_urls must be an array.' + inspect);
  const urls = [...new Set(finding.source_urls)];
  const matchedSources = urls.flatMap(url => {
    const matches = sources.filter(source => source.url === url);
    if (!matches.length) throw new Error('Finding ' + (index + 1) + ' cites a URL absent from successful search results.' + inspect);
    return matches;
  });
  if (finding.assessment !== 'not_established' && !matchedSources.some(source => source.snippet.trim())) {
    throw new Error('Finding ' + (index + 1) + ' needs a recorded snippet for its evidence assessment.' + inspect);
  }
  return {
    topic: text(finding.topic, 'topic'),
    finding: text(finding.finding, 'finding'),
    assessment: finding.assessment,
    source_ids: matchedSources.map(source => source.id),
    source_urls: urls,
    next_action: text(finding.next_action, 'next_action'),
    verification: text(finding.verification, 'verification'),
  };
});
const openQuestions = report.open_questions.map((question) => text(question, 'open_questions'));
if (!findings.length && !openQuestions.length) throw new Error('The report needs findings or concrete open questions.' + inspect);
// Escape display text only; preserve original responses and snippets in the evidence JSON.
const markdown = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\\`*_{}\[\]()#+.!|~-]/g, '\\$&').replace(/\r?\n/g, ' ');
const link = source => '[' + source.id + '](<' + source.url + '>)';
const lines = [
  '# API integration preparation brief', '',
  '## Task', '', markdown(task.question), '',
  '**Context:** ' + markdown(task.context), '',
  '## Summary', '', markdown(summary), '',
  '## Evidence and implementation checklist', '',
  'Evidence assessments below are the Agent\'s judgments, not independently verified facts. Source IDs are checked against recorded search results; that check does not establish that a snippet supports a claim.', '',
  '| Check | Finding | Agent assessment | Sources | Recommended next action | How to verify |',
  '| --- | --- | --- | --- | --- | --- |',
];
for (const finding of findings) {
  const citations = finding.source_ids.map(id => link(sources.find(source => source.id === id))).join(', ') || 'None recorded';
  lines.push('| ' + [markdown(finding.topic), markdown(finding.finding), finding.assessment, citations, markdown(finding.next_action), markdown(finding.verification)].join(' | ') + ' |');
}
if (!findings.length) lines.push('| No findings | No usable findings were produced | not_established | None recorded | Review the open questions below | Obtain evidence before implementation |');
lines.push('', '## Source excerpts', '', 'These are the original returned snippets, not full pages. Collection time is not publication time. Open the linked documentation before relying on it.', '');
const citedIds = new Set(findings.flatMap(finding => finding.source_ids));
for (const source of sources.filter(source => citedIds.has(source.id))) {
  lines.push('### ' + source.id + ': ' + (markdown(source.title) || 'Untitled result'), '', link(source), '', '> ' + (markdown(source.snippet) || 'No snippet returned.'), '', 'Search ' + source.search_number + ', result ' + source.result_number + '; collected: ' + markdown(source.collected_at ?? 'unknown') + '.', '');
}
if (!citedIds.size) lines.push('No source excerpts were cited.', '');
lines.push('## Open questions', '');
lines.push(...(openQuestions.length ? openQuestions.map(question => '- [ ] ' + markdown(question)) : ['The Agent listed no open questions. Human review of the sources is still required.']));
lines.push('', '## Search execution record', '');
lines.push(...(searches.length ? searches.map((search, i) =>
  '- Search ' + (i + 1) + ': ' + markdown(JSON.stringify(search.query)) + ' — ' + search.status + '; results: ' + (search.returned_count ?? 'unknown') + '; Credits: ' + (search.credits ?? 'unknown')
) : ['No tool searches were recorded. This brief has no recorded web evidence; do not treat it as verified research.']));
const limitations = 'Search snippets only. Collection timestamps are not publication dates. Source matching does not verify factual support. Evidence assessments, recommendations and conclusions require human review. Model charges are separate and not included in flashdata_credits.';
lines.push('', '## Limits and costs', '', limitations, '');
const totalCredits = searches.length && searches.every(search => search.credits !== null)
  ? searches.reduce((sum, search) => sum + search.credits, 0) : null;
return [{ json: {
  content: lines.join('\n'),
  report_schema_version: '2',
  question: task.question, context: task.context, preferred_sources: task.preferred_sources,
  country: task.country, search_language: task.search_language, requested_results_per_search: task.results_per_search,
  evidence_status: searches.length ? 'searches_recorded' : 'no_searches_recorded',
  tool_calls: searches.length, flashdata_credits: totalCredits,
  summary, findings, open_questions: openQuestions, sources, limitations, searches,
} }];
